'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var zeros = require( '@stdlib/array/zeros' );
var isColumnMajor = require( '@stdlib/ndarray/base/assert/is-column-major-string' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var gfillRows = require( './../lib' ).ndarray;


// VARIABLES //

var LAYOUTS = [
	'row-major',
	'column-major'
];


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {string} order - storage layout
* @param {PositiveInteger} M - number of elements along each row
* @param {PositiveInteger} N - number of elements along each column
* @returns {Function} benchmark function
*/
function createBenchmark( order, M, N ) {
	var alpha;
	var sx1;
	var sx2;
	var X;

	alpha = zeros( M, 'generic' );
	X = zeros( M*N, 'generic' );

	if ( isColumnMajor( order ) ) {
		sx1 = 1;
		sx2 = M;
	} else { // order === 'row-major'
		sx1 = N;
		sx2 = 1;
	}
	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var z;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			z = gfillRows( M, N, alpha, 1, 0, X, sx1, sx2, 0 );
			if ( isnan( z[ i%z.length ] ) ) {
				b.fail( 'should not return NaN' );
			}
		}
		b.toc();
		if ( isnan( z[ i%z.length ] ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var shapes = [
		[ 10, 100000 ],
		[ 100, 10000 ],
		[ 1000, 1000 ],
		[ 10000, 100 ],
		[ 100000, 10 ]
	];
	var shape;
	var ord;
	var f;
	var i;
	var k;

	for ( k = 0; k < LAYOUTS.length; k++ ) {
		ord = LAYOUTS[ k ];
		for ( i = 0; i < shapes.length; i++ ) {
			shape = shapes[ i ];
			f = createBenchmark( ord, shape[ 0 ], shape[ 1 ] );
			bench( format( '%s::matrix:ndarray:order=%s:M=%d:N=%d:size=%d', pkg, ord, shape[ 0 ], shape[ 1 ], shape[ 0 ] * shape[ 1 ] ), f );
		}
	}
}

main();
